const P = [
  { id: '964775386a3ce03ecca883.03770715', name: 'Realchecker (FE)' },
  { id: '852017176a3ce11141ecd5.60405885', name: 'Realchecker (BE)' }
];
const out = [];
for (const p of P) {
  for (let page = 1; page <= 25; page++) {
    out.push({ json: { project_id: p.id, project_name: p.name, page: page } });
  }
}
return out;

const reqs = $('Build Page Requests').all();
const res = $input.all();
const HAN = /[\u2E80-\u2FDF\u3005\u3007\u3021-\u3029\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]|[\uD840-\uD87F][\uDC00-\uDFFF]/;
const KANA = /[\u3040-\u30FF]/;
const hits = [];
const stats = {};
for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  const meta = (reqs[idx] || reqs[i]).json;
  const r = res[i].json || {};
  const st = stats[meta.project_name] || { pages_ok: 0, total: null, ko_seen: 0, errors: [] };
  if (r.statusCode !== 200) { if (r.statusCode !== undefined) { st.errors.push(meta.page + ':' + r.statusCode); } stats[meta.project_name] = st; continue; }
  const hdr = r.headers || {};
  if (hdr['x-pagination-total-count']) { st.total = parseInt(hdr['x-pagination-total-count'], 10); }
  const tr = (r.body && r.body.translations) ? r.body.translations : [];
  if (tr.length > 0) { st.pages_ok++; }
  for (const t of tr) {
    const iso = String(t.language_iso || '').toLowerCase();
    if (iso !== 'ko' && iso.indexOf('ko_') !== 0 && iso.indexOf('ko-') !== 0) { continue; }
    st.ko_seen++;
    const v = (typeof t.translation === 'string') ? t.translation : JSON.stringify(t.translation);
    if (HAN.test(v) || KANA.test(v)) {
      hits.push({ project_id: meta.project_id, project_name: meta.project_name, key_id: t.key_id, translation_id: t.translation_id, language_iso: iso, ko: v, han: HAN.test(v), kana: KANA.test(v), modified_at: t.modified_at, modified_by_email: t.modified_by_email || '' });
    }
  }
  stats[meta.project_name] = st;
}
if (hits.length === 0) { return [{ json: { none: true, stats: stats } }]; }
return hits.map(function (h) { h.stats = stats; return { json: h }; });

const hits = $('Find Han In Korean').all();
const res = $input.all();
const rows = [];
let stats = null;
for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  const h = (hits[idx] || hits[i]).json;
  stats = h.stats;
  if (h.none) { continue; }
  const k = (res[i].json && res[i].json.body && res[i].json.body.key) ? res[i].json.body.key : {};
  let en = '';
  for (const t of (k.translations || [])) { if (String(t.language_iso).toLowerCase() === 'en') { en = t.translation; } }
  const kn = k.key_name || {};
  rows.push({ project: h.project_name, project_id: h.project_id, key_id: h.key_id, key: kn.web || kn.other || kn.ios || kn.android || '', archived: !!k.is_archived, tags: k.tags || [], en: en, ko: h.ko, han: h.han, kana: h.kana, modified_at: h.modified_at, modified_by: h.modified_by_email });
}
return [{ json: { count: rows.length, rows: rows, stats: stats } }];
